import{_ as a,C as d,o as i,c as l,a2 as o,j as n,a as t,E as g}from"./chunks/framework.CtQGab4e.js";const f=JSON.parse('{"title":"Exporteren voor 3D","description":"","frontmatter":{},"headers":[],"relativePath":"plattegrond/export-3d.md","filePath":"plattegrond/export-3d.md"}'),s={name:"plattegrond/export-3d.md"};function p(h,e,m,k,u,b){const r=d("Icon");return i(),l("div",null,[e[8]||(e[8]=o('<h1 id="exporteren-voor-3d" tabindex="-1">Exporteren voor 3D <a class="header-anchor" href="#exporteren-voor-3d" aria-label="Permalink to &quot;Exporteren voor 3D&quot;">​</a></h1><h2 id="uit-het-3d-paneel" tabindex="-1">Uit het 3D-paneel <a class="header-anchor" href="#uit-het-3d-paneel" aria-label="Permalink to &quot;Uit het 3D-paneel&quot;">​</a></h2><p>Tik in het <a href="./3d-paneel.html">3D-paneel</a> op <strong>Exporteren</strong> en vink aan wat je wilt:</p><table tabindex="0"><thead><tr><th>Vinkje</th><th>Wat je krijgt</th></tr></thead><tbody><tr><td><strong>Renders</strong> (.jpg)</td><td>Vier overzichten van het gebouw, en per constructie met twee of meer rijen een beeld met de maatlijnen en rijnummers. Met <strong>Alle constructies</strong> ook die met één rij.</td></tr><tr><td><strong>Berekeningen</strong> (.txt)</td><td>De berekening als tekst: per constructie de rijen en het totaal, met je correcties.</td></tr><tr><td><strong>Interactieve weergave</strong> (.html)</td><td>Het 3D-model in één bestand, om in een browser te draaien en constructies aan te klikken. Ook te openen door iemand zonder de teken-tool.</td></tr></tbody></table><p>Meer dan één bestand komt samen in <code>3D_&lt;titel&gt;.zip</code>. De titel van je notitie staat in de legenda en in de interactieve weergave; naar de 3D-server gaat hij niet mee.</p><p>De export gebruikt je correcties. Is de tekening gewijzigd na het genereren, dan waarschuwt het venster, maar exporteren kan gewoon.</p><p><strong>Rekensoftware</strong>: de constructies voer je voorlopig met de hand in je rekensoftware in, op basis van <em>Berekeningen.txt</em>.</p><div class="info custom-block"><p class="custom-block-title">Interactieve weergave op de iPad</p><p>Op de iPad opent een <code>.html</code>-bestand in de app Bestanden, en daar draait het 3D-model niet. Open het op een computer.</p></div><h2 id="het-3d-bestand" tabindex="-1">Het 3D-bestand <a class="header-anchor" href="#het-3d-bestand" aria-label="Permalink to &quot;Het 3D-bestand&quot;">​</a></h2>',9)),n("p",null,[e[0]||(e[0]=t("Open het menu ",-1)),g(r,{name:"menu"}),e[1]||(e[1]=t(" en kies ",-1)),e[2]||(e[2]=n("strong",null,"Exporteren voor 3D",-1)),e[3]||(e[3]=t(". Je krijgt het bestand ",-1)),e[4]||(e[4]=n("code",null,"3d_<titel>.json",-1)),e[5]||(e[5]=t(": de tekening zoals de 3D-server hem krijgt. Dit heb je normaal niet nodig. Gaat er iets mis bij het genereren, stuur dit bestand dan mee met het ",-1)),e[6]||(e[6]=n("strong",null,"verzoek-id",-1)),e[7]||(e[7]=t(" uit het log.",-1))]),e[9]||(e[9]=o('<h3 id="wat-er-meegaat" tabindex="-1">Wat er meegaat <a class="header-anchor" href="#wat-er-meegaat" aria-label="Permalink to &quot;Wat er meegaat&quot;">​</a></h3><p>Per verdieping met een hoogte en een referentiepunt:</p><ul><li>de <strong>schil</strong> van het gebouw: de gevels met hun begrenzing, isolatie en dakdata;</li><li>de <strong>ruimtes</strong> met hun eigenschap, installaties, gebouwdeel, plat dak en kelder;</li><li>de <strong>hoogtes</strong> per verdieping en per gebouwdeel;</li><li>de <strong>oriëntatie</strong> en de lijst met isolaties.</li></ul><p>Binnenmuren gaan alleen mee als ze twee zones of twee gebouwdelen scheiden, of als ze dakdata hebben. De 3D-server maakt alleen de buitenkant van het gebouw. Hulplijnen gaan mee waar ze een grens zijn.</p><p>Vrije tekeningen, tekst, vormen en afbeeldingen gaan niet mee.</p><h2 id="meldingen" tabindex="-1">Meldingen <a class="header-anchor" href="#meldingen" aria-label="Permalink to &quot;Meldingen&quot;">​</a></h2><p>Bij <strong>Genereer</strong> staan deze meldingen in het log van het 3D-paneel, bij <strong>Exporteren voor 3D</strong> linksboven in rood. Het genereren of exporteren gaat wel gewoon door.</p><table tabindex="0"><thead><tr><th>Melding</th><th>Wat er aan de hand is</th><th>Oplossing</th></tr></thead><tbody><tr><td><em>Geen referentiepunt, overgeslagen: …</em></td><td>Die verdieping heeft een hoogte, maar geen gekoppelde hoek. Hij ontbreekt in 3D.</td><td>Koppel een <a href="./gebouw.html#referentiepunten">referentiepunt</a>.</td></tr><tr><td><em>… heeft geen hoogte: Z=0 ligt op een ontbrekende verdieping</em></td><td>De begane grond heeft geen hoogte.</td><td>Vul de hoogte van de begane grond in.</td></tr><tr><td><em>… geen enkel gebouwdeel ligt op het maaiveld</em></td><td>Elk gebouwdeel heeft een <strong>Vloer boven maaiveld</strong> groter dan 0.</td><td>Zet die van het laagste gebouwdeel op 0, zie <a href="./gebouw.html#gebouwdelen">Gebouwdelen</a>.</td></tr><tr><td><em>… heeft geen hoogte op …</em></td><td>Een ruimte hoort bij een gebouwdeel dat op die verdieping geen hoogte heeft. De hoogte van het hoofdhuis wordt gebruikt.</td><td>Vul de hoogte van het gebouwdeel in, of wijs de ruimte aan een ander gebouwdeel toe.</td></tr><tr><td><em>… plat dak met een eigen hoogte onder een verdieping erboven</em></td><td>Een plat dak met een afwijkende hoogte ligt onder een andere verdieping. Die hoogte wordt genegeerd.</td><td>Haal de hoogte weg, of maak er een <a href="./gebouw.html#gebouwdelen">gebouwdeel</a> van.</td></tr><tr><td><em>… een dakkapel op een binnenmuur of losse lijn wordt genegeerd</em></td><td>De dakkapel (of steekkap) staat niet op een gevel.</td><td>Zet hem op het gevelsegment. Zie <a href="./../hoe-teken-ik/dakkapel.html">Dakkapel</a>.</td></tr><tr><td><em>… kelder onder een vlak … genegeerd</em></td><td>De kelder klopt niet: geen hoogte, dieper onder het maaiveld dan hij hoog is, tot aan het plafond, niet op de begane grond, op een niet-berekend vlak, of boven een getekende kelder.</td><td>Pas de kelder aan in de <a href="./vlakken.html#kelder">vlak-popup</a>.</td></tr></tbody></table><p>Kijk ook in <a href="./../grenzen.html">Wat kan (nog) niet</a>.</p>',9))])}const w=a(s,[["render",p]]);export{f as __pageData,w as default};
